/// <summary>
/// Collects the message of the first failed assertion when <c>OLK_EnvironmentDataSetupTestJob</c> runs a test outside the SysTest runner.
/// </summary>
internal final class OLK_EnvironmentDataSetupTestResult extends SysTestResult
{
    str firstFailure;
}

Method.Source:
public void addFailure(SysTestExecutable _test, str _message)
{
    int callStack = strScan(_message, '  Call stack:', 1, strLen(_message));

    if (!firstFailure)
    {
        firstFailure = callStack ? subStr(_message, 1, callStack - 1) : _message;
    }
}
